/* Home, briefing and keyboard-only panel navigation around the live world. */
(function(){
'use strict';
const W=MysteryWorld,UI=GameUI,$=id=>document.getElementById(id),store='blackline-playground-v1';
let world;try{world=W.restore(localStorage.getItem(store));}catch{world=W.restore(null);}
let renderer=null,started=false,homeHelp=false,modalKind='',sound=false;
const controls=[['W A S D','Move / strafe'],['← → / mouse','Turn / look'],['Shift','Walk faster'],['E','Inspect, talk, open doors, climb'],['H','Full-screen help'],['M / Tab','Map, breadcrumb trail, route planning'],['B / J','Evidence board / field notes'],['I / Esc','Case briefing / pause']];
const keysMarkup=()=>`<dl class="key-grid">${controls.map(([key,label])=>`<div><dt><kbd>${key}</kbd></dt><dd>${label}</dd></div>`).join('')}</dl>`;
$('preflight-keys').innerHTML=keysMarkup();
function score(){return UI.score();}
function saveWorld(){renderer?.save();}
function fullScreen(){try{const action=document.fullscreenElement?document.exitFullscreen():document.documentElement.requestFullscreen();action?.catch?.(()=>{});}catch{}}
function isTyping(el){return el?.isContentEditable||['INPUT','TEXTAREA','SELECT'].includes(el?.tagName);}
function showPanel(title,body,kicker,kind){modalKind=kind;UI.open(title,body,kicker);$('inspection').dataset.screen=kind;$('panel-score').textContent=score()+' POINTS';assignChoices();}
function closePanel(){if($('inspection').open)UI.close();else if(!$('workspace').hidden)UI.view('field');}
function sync(){const s=UI.getState();$('panel-score').textContent=score()+' POINTS';$('workspace-score').textContent=score()+' POINTS';if(!started||!$('home').hidden){$('workspace').hidden=true;document.body.dataset.mode='home';renderer?.setRunning(false);assignChoices();return;}const workspace=s.view!=='field'||!!s.ending;$('workspace').hidden=!workspace;if(workspace){document.body.dataset.mode='panel';renderer?.setRunning(false);$('workspace-title').textContent=s.ending&&s.view==='field'?'Case disposition':s.view==='board'?'Evidence board':'Field notes';}else if(!started||!$('home').hidden){document.body.dataset.mode='home';renderer?.setRunning(false);}else if($('inspection').open){document.body.dataset.mode='panel';renderer?.setRunning(false);}else{document.body.dataset.mode='playing';renderer?.setRunning(true);}assignChoices();}
function buildRenderer(){if(renderer)return true;try{renderer=new MysteryRenderer($('world'),world,interact);Playground.renderer=renderer;return true;}catch(e){showPanel('The world could not start',`<p>The browser could not initialize the WebGL scene.</p><p>${escapeText(e.message)}</p><p>Your case progress is preserved. Enable WebGL in a supported browser and reload.</p>`,'RENDERER / STARTUP','error');return false;}}
function escapeText(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function openBriefing(continuing){$('home-menu').hidden=true;$('briefing').hidden=false;$('begin-inspection').focus();}
function begin(){if(!buildRenderer())return;started=true;homeHelp=false;$('home').hidden=true;$('briefing').hidden=true;UI.view('field');renderer.visit();sync();}
function freshCase(){const hasProgress=UI.getState().clues.length||world.trail.length;if(hasProgress){showPanel('Begin a new case?',`<p>This starts a fresh investigation and clears the current case’s discoveries, route history, notes, and position in this browser.</p><div class="option-list"><button id="confirm-new">Start a new case</button><button id="cancel-new">Keep this investigation</button></div>`,'HOME / CASE SELECTION','new');$('confirm-new').onclick=()=>{UI.close();resetCase();};$('cancel-new').onclick=()=>UI.close();}else resetCase();}
function resetCase(){UI.reset();Object.assign(world,W.restore(null));if(renderer){renderer.world=world;renderer.zEye=0;renderer.pitch=0;renderer.climb=null;renderer.traveled=0;}saveWorld();openBriefing(false);}
function returnHome(){started=false;closePanel();$('home').hidden=false;$('home-menu').hidden=false;$('briefing').hidden=true;document.body.dataset.mode='home';renderer?.setRunning(false);const has=UI.getState().clues.length||world.trail.length;$('continue-case').hidden=!has;$('new-case').querySelector('kbd').hidden=!!has;$('continue-case').textContent=UI.getState().ending?'Review completed case':'Continue investigation';$('continue-case').focus();}
function recordContact(id){const found=UI.contact(id);if(found)renderer?.tone(650);return found;}
function interact(object){if(UI.getState().ending){UI.view('field');return;}UI.setPlace(W.roomAt(world.pose).zone);saveWorld();if(object.discovery&&UI.record(object.discovery))renderer?.tone(850);if(object.kind==='person'){recordContact(object.id);if(['Vale','Imani','Kade'].includes(object.id)){modalKind='interview';UI.person(object.id);$('inspection').dataset.screen='interview';assignChoices();}else supportInterview(object.id);return;}if(W.extras.some(e=>e.id===object.id)){const found=UI.record(object.id),e=Blackline.extraEvidence[object.id];if(found)renderer?.tone(850);showPanel(e.title,`<article class="paper"><small>RECOVERED RECORD / DIRECTORATE</small><h3>${e.title}</h3><p>${e.text}</p></article><p class="record-reward">${found?'+40 POINTS · NEW DISCOVERY':'ALREADY RECORDED · NO DUPLICATE POINTS'}</p>`,'FIELD DISCOVERY / SUPPORTING MATERIAL','discovery');return;}if(object.id==='assessment'){modalKind='assessment';UI.assessment();assignChoices();return;}modalKind='inspection';UI.inspect(object.id);$('inspection').dataset.screen='inspection';assignChoices();}
const support={
 Marin:{title:'Officer Marin',role:'ARRIVAL SECURITY',intro:'“Follow the records. This building has plenty of stories.”',questions:[['Where should I begin?','“The crisis room is west of the atrium. The harbor cable and leaked dossier are there. The security office is to the east.”'],['Where are the others?','“Vale stayed in the crisis wing. Imani is working in the upper observation gallery. Kade is in the upper liaison office. Take the stairs from the atrium, or use the wing stairs.”'],['How do I find my way?','“M opens the building map. Your cyan trail records where you have actually walked. Choose a room there to calculate a route. T toggles the gold floor guidance.”']]},
 Sato:{title:'Archivist Sato',role:'RECORDS CUSTODIAN',intro:'“A redacted page and a safe file are not the same thing.”',questions:[['What records are here?','“The revision archive and source annex. Compare the confidence wording, then inspect the PDF’s underlying text. The release checklist is also worth reading.”'],['Can an account name identify the leaker?','“An author field names an account. A registered device, physical identification, and a matching upload make a much stronger chain. The security office holds those records.”'],['Is there another way down?','“The west staircase leads to the crisis wing. The maintenance ladder is just beyond the south edge of the archive. Face it and press E to climb.”']]},
 Ortega:{title:'Technician Ortega',role:'FACILITIES / SERVICE WORKSHOP',intro:'“The upper galleries are connected. You do not have to retrace every corridor.”',questions:[['How do I get upstairs?','“There are stairs north of the crisis room and security office, plus a central stair from the atrium. Keep walking to climb them. The steps have yellow safety edges.”'],['What about the maintenance ladder?','“Go north from the crisis room’s west side. The ladder is in the low maintenance bay below the archive. Stand near it, face it, and press E. It works both ways.”'],['What is this chart?','“The route chart on the workshop table shows the building’s access routes. It is a supporting discovery; the actual case is in the records and conversations.”']]}
};
function supportInterview(id){const p=support[id];showPanel(p.title,`<div class="support-speaker"><div class="person-emblem" aria-hidden="true">${id[0]}</div><div><p class="eyebrow">${p.role}</p><p>${p.intro}</p></div></div><div class="option-list">${p.questions.map(([q],i)=>`<button data-question="${i}">${q}</button>`).join('')}</div><div id="support-response" class="response" role="status"><p>Choose a question. New contacts earn 25 points once.</p></div>`,'PERSONNEL / CONVERSATION','interview');document.querySelectorAll('[data-question]').forEach(b=>b.onclick=()=>{$('support-response').innerHTML=`<p>${p.questions[Number(b.dataset.question)][1]}</p>`;});}
function briefing(){const s=UI.getState(),room=W.roomAt(world.pose),finds=s.clues.map(id=>`<li>${Blackline.evidence[id].title}</li>`).join('');showPanel('The Meridian Leak',`<div class="briefing-grid"><section><p class="eyebrow">CURRENT MANDATE</p><h3>Identify the leak. Choose what to release.</h3><p>A source list escaped the network. The leaked briefing claims a blockade is confirmed, but the original estimate says otherwise. Build a defensible attribution and protect the people in the source annex.</p><h3>Your next lead</h3><p>${$('lead').textContent}</p><div class="option-list"><button id="panel-hint">Request a field hint</button><button id="panel-assess">File your assessment</button></div></section><section><div class="score-display"><strong>${score()}</strong><span>INVESTIGATION POINTS</span></div><dl class="case-statistics"><div><dt>Main findings</dt><dd>${s.clues.length} / 8</dd></div><div><dt>Supporting records</dt><dd>${s.discoveries.length} / 7</dd></div><div><dt>People contacted</dt><dd>${s.contacts.length} / 6</dd></div><div><dt>Evidence links</dt><dd>${s.links.length} / 3</dd></div><div><dt>Current area</dt><dd>${room.name}</dd></div><div><dt>Summit countdown</dt><dd>${$('remaining').textContent}</dd></div></dl></section></div><section><h3>Recorded findings</h3><ul class="record-list">${finds||'<li>No main findings recorded yet.</li>'}</ul></section><p class="panel-note">Only discoveries advance the story clock. Movement, help, the map, and rechecking records are free.</p>`,'CASE 007 / OBJECTIVES & SCORE','briefing');$('panel-hint').onclick=()=>UI.hint();$('panel-assess').onclick=()=>{modalKind='assessment';UI.assessment();assignChoices();};}
function mapMarkup(){const visited=new Set(world.visited),dest=W.rooms.find(r=>r.id===world.routeTo),path=dest?W.route(world.pose,dest):[],points=a=>a.map(p=>p.x.toFixed(2)+','+p.y.toFixed(2)).join(' ');let tiles='';for(let y=0;y<W.height;y++)for(let x=0;x<W.width;x++){const c=W.cells[y][x];if(!c)continue;const seen=visited.has(y*W.width+x),color=c.material==='stairs'?'#ac8c4c':c.z>.8?'#587862':'#395e59';tiles+=`<rect x="${x}" y="${y}" width=".94" height=".94" fill="${color}" opacity="${seen?'.95':'.24'}"/>`;}
 const npcs=W.people.filter(n=>visited.has(Math.floor(n.y)*W.width+Math.floor(n.x))).map(n=>`<circle cx="${n.x}" cy="${n.y}" r=".27" fill="#d9bb82"><title>${n.name}</title></circle>`).join('');const angle=world.pose.angle*180/Math.PI+90;return `<div class="automap-layout"><section><svg id="automap" viewBox="0 0 ${W.width} ${W.height}" role="img" aria-label="Directorate map. Cyan records your walked path; gold is the planned route. Upper galleries are green, stairs amber."><rect width="${W.width}" height="${W.height}" fill="#071416"/>${tiles}<polyline points="${points(world.trail)}" fill="none" stroke="#74d5c0" stroke-width=".18" opacity=".85"/>${path.length?`<polyline points="${points(path)}" fill="none" stroke="#f0bf66" stroke-width=".22" stroke-dasharray=".6 .4"/>`:''}${W.doors.map(d=>`<rect x="${d.x-.15}" y="${d.y-1}" width=".3" height="2" fill="${world.opened.includes(d.id)?'#5d8875':'#bf8d5d'}"/>`).join('')}${npcs}<circle cx="7.5" cy="15" r=".35" fill="none" stroke="#e1d7ad" stroke-width=".12"/><g transform="translate(${world.pose.x} ${world.pose.y}) rotate(${angle})"><path d="M0-.65.4.45 0 .2-.4.45Z" fill="#f1ebd1"/></g>${W.rooms.map((r,i)=>`<text x="${r.x}" y="${r.y+1.7}" text-anchor="middle" fill="#dde6ce" font-size=".85" font-family="monospace">${i+1}</text>`).join('')}</svg><div class="map-legend"><span><i class="cyan"></i>Walked trail</span><span><i class="gold"></i>Planned route</span><span>Amber: stairs · Ring: ladder · Dots: people</span></div></section><aside><p class="eyebrow">PLAN A ROUTE / KEYS 1–8</p><div class="map-destinations">${W.rooms.map((r,i)=>`<button data-destination="${r.id}" class="${r.id===world.routeTo?'active':''}"><kbd>${i+1}</kbd><span>${r.name}<small>${r.z>0?'UPPER GALLERY':'GROUND FLOOR'}</small></span></button>`).join('')}</div><p class="route-summary">${dest?`${Math.max(0,path.length-1)} tiles to ${dest.name}. Follow the gold route. Closed doors can be opened with E.`:'Select a destination. Routes use the connected stairs and corridors; this map does not teleport you.'}</p><button id="toggle-route">Gold floor guidance: ${world.showRoute?'on':'off'} <kbd>T</kbd></button><p class="panel-note">You are in ${W.roomAt(world.pose).name}. Your actual trail and explored cells are saved automatically. Faint rooms are unvisited blueprint areas.</p></aside></div>`;}
function automap(){saveWorld();showPanel('Directorate automap',mapMarkup(),'NAVIGATION / ACTUAL TRAIL & PLANNED ROUTE','map');document.querySelectorAll('[data-destination]').forEach(b=>b.onclick=()=>setDestination(b.dataset.destination));$('toggle-route').onclick=toggleRoute;}
function setDestination(id){world.routeTo=id;saveWorld();automap();}
function toggleRoute(){world.showRoute=!world.showRoute;saveWorld();if(modalKind==='map')automap();}
function help(){homeHelp=!started;showPanel('Field manual',`<div class="help-layout"><section><h3>Explore without a HUD</h3>${keysMarkup()}<p><kbd>T</kbd> Toggle planned-route floor lights · <kbd>F</kbd> Fullscreen · <kbd>N</kbd> Sound</p><p>The world has no menu buttons or floating labels. Physical signs name the rooms. Move close to a dossier, terminal, ladder, door, or person; face it and press E. A focused object subtly brightens.</p><p>Click the world to capture the mouse. Escape releases it and pauses. Arrow keys or dragging also let you look around.</p></section><section><h3>Work the case</h3><ol class="manual-list"><li>Find the original estimate, leaked revision, source annex, access log, CCTV footage, upload, independent cable, and deleted messages.</li><li>Question the three suspects. Marin, Sato, and Ortega can help you navigate or interpret the records.</li><li>Open B and connect evidence cards to establish the chain. Keep theories in J.</li><li>Use I to check your lead and score. File your assessment there or at the atrium’s case terminal.</li></ol><h3>Stairs, ladder, and map</h3><p>Walk up and down the yellow-edged steps. For the west maintenance ladder, face the rungs and press E; the climb is animated and works in both directions. M or Tab shows your map and actual trail. Keys 1–8 in the map plan a route.</p><h3>Points that mean progress</h3><p>Each main finding earns 100 points. Supporting records earn 40, first conversations 25, and valid evidence links 75. The fully supported, source-safe resolution adds 300. Nothing awards points twice.</p><p class="panel-note">Shortcuts never interrupt typing. Within case panels, numbered choices, Tab, Enter, and the mouse work. Escape returns to the world. Desktop keyboard controls are required for exploration.</p></section></div>`,'BLACKLINE / CONTROLS & INVESTIGATION','help');}
function pause(){showPanel('Investigation paused',`<p class="panel-intro">The world is paused. Your route, discoveries, and position are saved locally.</p><div class="pause-options"><button id="pause-resume">Resume investigation <kbd>Esc</kbd></button><button id="pause-map">Map & route planning <kbd>M</kbd></button><button id="pause-brief">Objectives & score <kbd>I</kbd></button><button id="pause-help">Field manual <kbd>H</kbd></button><button id="pause-home">Return to home screen</button></div>`,'BLACKLINE / CASE MENU','pause');$('pause-resume').onclick=()=>UI.close();$('pause-map').onclick=automap;$('pause-brief').onclick=briefing;$('pause-help').onclick=help;$('pause-home').onclick=returnHome;}
function assignChoices(){const root=$('inspection');if(!root.open)return;const buttons=[...$('dialog-content').querySelectorAll('button')].filter(b=>!b.disabled&&!b.closest('.map-destinations')&&b.id!=='toggle-route');buttons.forEach((b,i)=>{if(i>8)return;if(!b.querySelector('.choice-key')){const k=document.createElement('kbd');k.className='choice-key';k.textContent=String(i+1);b.append(k);}b.dataset.choiceKey=String(i+1);});}
const observer=new MutationObserver(()=>assignChoices());observer.observe($('dialog-content'),{childList:true,subtree:true});
document.addEventListener('blackline:new-case',()=>{returnHome();freshCase();});document.addEventListener('blackline:render',sync);$('inspection').addEventListener('close',()=>{modalKind='';if(homeHelp||!started){homeHelp=false;document.body.dataset.mode='home';renderer?.setRunning(false);}else sync();});$('back-world').onclick=()=>UI.view('field');
$('continue-case').onclick=()=>openBriefing(true);$('new-case').onclick=freshCase;$('home-controls').onclick=help;$('begin-inspection').onclick=begin;
document.addEventListener('pointerlockchange',()=>{if(started&&renderer?.running&&!document.pointerLockElement&&document.body.dataset.mode==='playing')pause();});
document.addEventListener('keydown',e=>{if(e.ctrlKey||e.metaKey||e.altKey||e.repeat)return;const key=e.key.toLowerCase();if(isTyping(e.target)){if(e.key==='Escape'){e.preventDefault();closePanel();}return;}if($('inspection').open){if(e.key==='Escape'){e.preventDefault();UI.close();return;}if(modalKind==='map'&&/^[1-8]$/.test(key)){e.preventDefault();setDestination(W.rooms[Number(key)-1].id);return;}if(modalKind==='map'&&key==='t'){e.preventDefault();toggleRoute();return;}if(/^[1-9]$/.test(key)){const b=$('dialog-content').querySelector(`[data-choice-key="${key}"]`);if(b){e.preventDefault();b.click();}}return;}
 if(!$('home').hidden){if(key==='h'||key==='?'){e.preventDefault();help();}else if(key==='f'){e.preventDefault();fullScreen();}else if(e.key==='Enter'){e.preventDefault();if(!$('briefing').hidden)begin();else if(!$('continue-case').hidden)openBriefing(true);else freshCase();}return;}
 if(key==='h'||key==='?'){e.preventDefault();help();}else if(key==='m'||e.key==='Tab'){e.preventDefault();automap();}else if(key==='b'){e.preventDefault();UI.view('board');}else if(key==='j'){e.preventDefault();UI.view('journal');}else if(key==='i'){e.preventDefault();briefing();}else if(key==='t'){e.preventDefault();toggleRoute();}else if(key==='f'){e.preventDefault();fullScreen();}else if(key==='n'){e.preventDefault();sound=!sound;renderer?.setSound(sound);}else if(e.key==='Escape'){e.preventDefault();if(!$('workspace').hidden)UI.view('field');else pause();}});
let hadSaved=false;try{hadSaved=!!localStorage.getItem(store);}catch{}const has=UI.getState().clues.length||hadSaved;$('continue-case').hidden=!has;$('new-case').querySelector('kbd').hidden=!!has;sync();(has?$('continue-case'):$('new-case')).focus();
})();
